begin;
create function pg_temp.ok(v boolean,label text) returns void language plpgsql as $$begin if v is distinct from true then raise exception 'FAILED: %',label;end if;end$$;
create function pg_temp.denied(q text) returns void language plpgsql as $$begin begin execute q;exception when insufficient_privilege then return;end;raise exception 'UNEXPECTEDLY ALLOWED: %',q;end$$;
insert into auth.users(id,email,email_confirmed_at,raw_user_meta_data) values('e1000000-0000-4000-8000-000000000001','supplier@upload.invalid',now(),'{}'),('e1000000-0000-4000-8000-000000000002','other@upload.invalid',now(),'{}');
update public.user_roles set role='supplier' where user_id in('e1000000-0000-4000-8000-000000000001','e1000000-0000-4000-8000-000000000002');
insert into public.businesses(id,owner_id,name,division,district) values('e2000000-0000-4000-8000-000000000001','e1000000-0000-4000-8000-000000000001','Synthetic upload supplier','Dhaka','Dhaka'),('e2000000-0000-4000-8000-000000000002','e1000000-0000-4000-8000-000000000002','Other upload supplier','Dhaka','Dhaka');
insert into public.products(id,business_id,category_id,name,description,price,moq) values('e3000000-0000-4000-8000-000000000001','e2000000-0000-4000-8000-000000000001',(select id from public.categories limit 1),'Ordinary product name','Synthetic upload testing only',100,10),('e3000000-0000-4000-8000-000000000002','e2000000-0000-4000-8000-000000000002',(select id from public.categories limit 1),'Other product name','Synthetic upload testing only',100,10);
set local request.jwt.claims='{"sub":"e1000000-0000-4000-8000-000000000001","role":"authenticated"}';set local role authenticated;
insert into storage.objects(bucket_id,name,metadata) values('product-images','e1000000-0000-4000-8000-000000000001/e3000000-0000-4000-8000-000000000001/synthetic.webp','{"mimetype":"image/webp","size":100}');
select pg_temp.ok((select count(*)=1 from storage.objects where name like 'e1000000%'),'own product path upload succeeds independently of product name');
select pg_temp.denied($$insert into storage.objects(bucket_id,name) values('product-images','e1000000-0000-4000-8000-000000000001/e3000000-0000-4000-8000-000000000002/other.webp')$$);
select pg_temp.denied($$insert into storage.objects(bucket_id,name) values('product-images','e1000000-0000-4000-8000-000000000002/e3000000-0000-4000-8000-000000000001/wrong-owner.webp')$$);
select pg_temp.denied($$insert into storage.objects(bucket_id,name) values('product-images','e1000000-0000-4000-8000-000000000001/00000000-0000-4000-8000-000000000000/missing.webp')$$);
reset role;update public.account_statuses set status='suspended',reason='Synthetic upload test' where user_id='e1000000-0000-4000-8000-000000000001';set local role authenticated;
select pg_temp.denied($$insert into storage.objects(bucket_id,name) values('product-images','e1000000-0000-4000-8000-000000000001/e3000000-0000-4000-8000-000000000001/suspended.webp')$$);
reset role;set local role anon;set local request.jwt.claims='{}';
select pg_temp.denied($$insert into storage.objects(bucket_id,name) values('product-images','e1000000-0000-4000-8000-000000000001/e3000000-0000-4000-8000-000000000001/guest.webp')$$);
reset role;
select 'Product upload authorization passed; synthetic fixtures rolled back.' result;
rollback;
